diff --git a/build.xml b/build.xml
index 8484d7cd9..a8d6449c7 100644
--- a/build.xml
+++ b/build.xml
@@ -28,8 +28,8 @@
   <property name="test.fork" value="true"/>

   <!-- Force java 6 -->
-  <property name="ant.build.javac.source" value="1.6" />
-  <property name="ant.build.javac.target" value="1.6" />
+  <property name="ant.build.javac.source" value="1.8" />
+  <property name="ant.build.javac.target" value="1.8" />

   <!-- define other variables -->
   <property name="javac.debug" value="on" />
diff --git a/lib/rhino/build.properties b/lib/rhino/build.properties
index e5503e720..c7f1bca36 100644
--- a/lib/rhino/build.properties
+++ b/lib/rhino/build.properties
@@ -21,8 +21,8 @@ classes: ${build.dir}/classes

 # compilation settings
 debug: on
-target-jvm 1.6
-source-level 1.6
+target-jvm 1.8
+source-level 1.8

 # jar generation settings
 jar-compression: true
diff --git a/src/com/google/javascript/jscomp/RemoveUnusedVars.java b/src/com/google/javascript/jscomp/RemoveUnusedVars.java
index dfad51bcc..a879a4235 100644
--- a/src/com/google/javascript/jscomp/RemoveUnusedVars.java
+++ b/src/com/google/javascript/jscomp/RemoveUnusedVars.java
@@ -390,14 +390,17 @@ class RemoveUnusedVars
         && callSiteOptimizer.canModifyCallers(function);
     if (!modifyCallers) {
       // Strip unreferenced args off the end of the function declaration.
-      Node lastArg;
-      while ((lastArg = argList.getLastChild()) != null) {
-        Var var = fnScope.getVar(lastArg.getString());
-        if (!referenced.contains(var)) {
-          argList.removeChild(lastArg);
-          compiler.reportCodeChange();
-        } else {
-          break;
+      // Only do this if removeGlobals is enabled (i.e., in ADVANCED mode).
+      if (removeGlobals) {
+        Node lastArg;
+        while ((lastArg = argList.getLastChild()) != null) {
+          Var var = fnScope.getVar(lastArg.getString());
+          if (!referenced.contains(var)) {
+            argList.removeChild(lastArg);
+            compiler.reportCodeChange();
+          } else {
+            break;
+          }
         }
       }
     } else {
